```tsx
// CheckoutPage.tsx
import React, { useMemo, useState } from 'react';
import './CheckoutPage.css';
import { CartItem, CheckoutPageProps, DeliveryAddress } from './types';

const EMPTY_ADDRESS: DeliveryAddress = {
  fullName: '',
  street: '',
  city: '',
  postalCode: '',
  country: '',
  phone: '',
};

type AddressErrors = Partial<Record<keyof DeliveryAddress, string>>;

function formatPrice(value: number): string {
  return value.toLocaleString(undefined, {
    style: 'currency',
    currency: 'USD',
  });
}

function validateAddress(address: DeliveryAddress): AddressErrors {
  const errors: AddressErrors = {};

  if (!address.fullName.trim()) {
    errors.fullName = 'Full name is required.';
  }
  if (!address.street.trim()) {
    errors.street = 'Street address is required.';
  }
  if (!address.city.trim()) {
    errors.city = 'City is required.';
  }
  if (!address.postalCode.trim()) {
    errors.postalCode = 'Postal code is required.';
  }
  if (!address.country.trim()) {
    errors.country = 'Country is required.';
  }
  if (!address.phone.trim()) {
    errors.phone = 'Phone number is required.';
  } else if (!/^[+\d][\d\s-]{6,}$/.test(address.phone.trim())) {
    errors.phone = 'Enter a valid phone number.';
  }

  return errors;
}

const CartSummary: React.FC<{ items: CartItem[] }> = ({ items }) => {
  const subtotal = useMemo(
    () => items.reduce((sum, item) => sum + item.price * item.quantity, 0),
    [items]
  );
  const shipping = items.length > 0 ? 5.99 : 0;
  const total = subtotal + shipping;

  return (
    <section className="checkout-section cart-summary" aria-labelledby="cart-summary-heading">
      <h2 id="cart-summary-heading" className="checkout-section__title">
        Your order
      </h2>

      {items.length === 0 ? (
        <p className="cart-summary__empty">Your cart is empty.</p>
      ) : (
        <ul className="cart-summary__list">
          {items.map((item) => (
            <li key={item.id} className="cart-summary__item">
              <img
                className="cart-summary__image"
                src={item.imageUrl}
                alt={item.name}
                width={64}
                height={64}
              />
              <div className="cart-summary__info">
                <p className="cart-summary__name">{item.name}</p>
                <p className="cart-summary__qty">Qty: {item.quantity}</p>
              </div>
              <p className="cart-summary__line-price">
                {formatPrice(item.price * item.quantity)}
              </p>
            </li>
          ))}
        </ul>
      )}

      <div className="cart-summary__totals">
        <div className="cart-summary__row">
          <span>Subtotal</span>
          <span>{formatPrice(subtotal)}</span>
        </div>
        <div className="cart-summary__row">
          <span>Shipping</span>
          <span>{formatPrice(shipping)}</span>
        </div>
        <div className="cart-summary__row cart-summary__row--total">
          <span>Total</span>
          <span>{formatPrice(total)}</span>
        </div>
      </div>
    </section>
  );
};

export const CheckoutPage: React.FC<CheckoutPageProps> = ({
  items,
  onBackToCart,
  onPay,
  isSubmitting = false,
}) => {
  const [address, setAddress] = useState<DeliveryAddress>(EMPTY_ADDRESS);
  const [errors, setErrors] = useState<AddressErrors>({});

  const handleChange = (field: keyof DeliveryAddress) => (
    event: React.ChangeEvent<HTMLInputElement>
  ) => {
    setAddress((prev) => ({ ...prev, [field]: event.target.value }));
  };

  const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();

    const validationErrors = validateAddress(address);
    setErrors(validationErrors);

    if (Object.keys(validationErrors).length === 0) {
      onPay(address);
    }
  };

  const hasItems = items.length > 0;

  return (
    <div className="checkout-page">
      <div className="checkout-page__container">
        <button
          type="button"
          className="checkout-page__back-link"
          onClick={onBackToCart}
        >
          &larr; Back to cart
        </button>

        <h1 className="checkout-page__title">Checkout</h1>

        <div className="checkout-page__layout">
          <CartSummary items={items} />

          <section className="checkout-section delivery-form" aria-labelledby="delivery-form-heading">
            <h2 id="delivery-form-heading" className="checkout-section__title">
              Delivery address
            </h2>

            <form className="delivery-form__form" onSubmit={handleSubmit} noValidate>
              <div className="form-field">
                <label htmlFor="fullName">Full name</label>
                <input
                  id="fullName"
                  type="text"
                  autoComplete="name"
                  value={address.fullName}
                  onChange={handleChange('fullName')}
                  aria-invalid={Boolean(errors.fullName)}
                  aria-describedby={errors.fullName ? 'fullName-error' : undefined}
                />
                {errors.fullName && (
                  <span id="fullName-error" className="form-field__error">
                    {errors.fullName}
                  </span>
                )}
              </div>

              <div className="form-field">
                <label htmlFor="street">Street address</label>
                <input
                  id="street"
                  type="text"
                  autoComplete="street-address"
                  value={address.street}
                  onChange={handleChange('street')}
                  aria-invalid={Boolean(errors.street)}
                  aria-describedby={errors.street ? 'street-error' : undefined}
                />
                {errors.street && (
                  <span id="street-error" className="form-field__error">
                    {errors.street}
                  </span>
                )}
              </div>

              <div className="form-field-row">
                <div className="form-field">
                  <label htmlFor="city">City</label>
                  <input
                    id="city"
                    type="text"
                    autoComplete="address-level2"
                    value={address.city}
                    onChange={handleChange('city')}
                    aria-invalid={Boolean(errors.city)}
                    aria-describedby={errors.city ? 'city-error' : undefined}
                  />
                  {errors.city && (
                    <span id="city-error" className="form-field__error">
                      {errors.city}
                    </span>
                  )}
                </div>

                <div className="form-field">
                  <label htmlFor="postalCode">Postal code</label>
                  <input
                    id="postalCode"
                    type="text"
                    autoComplete="postal-code"
                    value={address.postalCode}
                    onChange={handleChange('postalCode')}
                    aria-invalid={Boolean(errors.postalCode)}
                    aria-describedby={errors.postalCode ? 'postalCode-error' : undefined}
                  />
                  {errors.postalCode && (
                    <span id="postalCode-error" className="form-field__error">
                      {errors.postalCode}
                    </span>
                  )}
                </div>
              </div>

              <div className="form-field">
                <label htmlFor="country">Country</label>
                <input
                  id="country"
                  type="text"
                  autoComplete="country-name"
                  value={address.country}
                  onChange={handleChange('country')}
                  aria-invalid={Boolean(errors.country)}
                  aria-describedby={errors.country ? 'country-error' : undefined}
                />
                {errors.country && (
                  <span id="country-error" className="form-field__error">
                    {errors.country}
                  </span>
                )}
              </div>

              <div className="form-field">
                <label htmlFor="phone">Phone number</label>
                <input
                  id="phone"
                  type="tel"
                  autoComplete="tel"
                  value={address.phone}
                  onChange={handleChange('phone')}
                  aria-invalid={Boolean(errors.phone)}
                  aria-describedby={errors.phone ? 'phone-error' : undefined}
                />
                {errors.phone && (
                  <span id="phone-error" className="form-field__error">
                    {errors.phone}
                  </span>
                )}
              </div>

              <div className="checkout-page__actions">
                <button
                  type="button"
                  className="btn btn--secondary"
                  onClick={onBackToCart}
                  disabled={isSubmitting}
                >
                  Back to cart
                </button>
                <button
                  type="submit"
                  className="btn btn--primary"
                  disabled={!hasItems || isSubmitting}
                >
                  {isSubmitting ? 'Processing…' : 'Pay'}
                </button>
              </div>
            </form>
          </section>
        </div>
      </div>
    </div>
  );
};

export default CheckoutPage;
```

