Usage example (not required, just for reference on wiring it up):

```tsx
// App.tsx (example wiring, not part of the component)
import React, { useState } from 'react';
import CheckoutPage from './CheckoutPage';
import { CartItem, DeliveryAddress } from './types';

const sampleItems: CartItem[] = [
  { id: '1', name: 'Wireless Headphones', imageUrl: '/images/headphones.jpg', price: 79.99, quantity: 1 },
  { id: '2', name: 'USB-C Cable', imageUrl: '/images/cable.jpg', price: 9.99, quantity: 2 },
];

export default function App() {
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handlePay = async (address: DeliveryAddress) => {
    setIsSubmitting(true);
    try {
      await fakeCheckoutApiCall(address);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <CheckoutPage
      items={sampleItems}
      onBackToCart={() => console.log('navigate back to cart')}
      onPay={handlePay}
      isSubmitting={isSubmitting}
    />
  );
}

function fakeCheckoutApiCall(address: DeliveryAddress) {
  return new Promise((resolve) => setTimeout(resolve, 1000));
}
```

Notes on the design:
- The Pay button is disabled while the cart is empty or a submission is in flight, so users can't trigger a charge with nothing to pay for.
- Form validation runs on submit and surfaces inline errors per field, with `aria-invalid`/`aria-describedby` wired for screen readers.
- Layout is a two-column grid (summary + form) that collapses to a single column under 760px.
